def resolve(path, cwd, links):
    if path.startswith('/'):
        current = '/'
        remaining = path[1:]
    else:
        current = cwd
        remaining = path

    link_count = 0

    while remaining:
        # Split by '/' and process components
        parts = remaining.split('/')
        remaining = ''

        for i, part in enumerate(parts):
            if not part or part == '.':
                # Skip empty components and '.'
                continue
            elif part == '..':
                # Move to parent
                if current != '/':
                    current = current.rsplit('/', 1)[0]
                    if not current:
                        current = '/'
            else:
                # Append the component
                if current == '/':
                    current = '/' + part
                else:
                    current = current + '/' + part

                # Check if current path is a symlink
                if current in links:
                    link_count += 1
                    if link_count > 8:
                        return None

                    target = links[current]

                    # Construct remaining path from target and rest of components
                    rest_of_components = parts[i + 1:]
                    if target.startswith('/'):
                        current = '/'
                        remaining = target[1:]
                    else:
                        # Target is relative to the directory containing the link
                        if current != '/':
                            current = current.rsplit('/', 1)[0]
                            if not current:
                                current = '/'
                        remaining = target

                    # Append remaining components
                    if rest_of_components:
                        if remaining:
                            remaining = remaining + '/' + '/'.join(rest_of_components)
                        else:
                            remaining = '/'.join(rest_of_components)

                    break

    # Remove trailing slash except for '/'
    if current != '/' and current.endswith('/'):
        current = current.rstrip('/')

    return current

